    if (*q == '+') q++;
    else if (*q == '-') { sign = -1; q++; }
    int base = 10;
    if (q[0] == '0' && q[1] == 'x') { base = 16; q += 2; }
    else if (q[0] == '0' && q[1] == 'o') { base = 8;  q += 2; }
    else if (q[0] == '0' && q[1] == 'b') { base = 2;  q += 2; }
    return (int64_t)sign * (int64_t)strtoull(q, NULL, base);
