/* Decode a basic-string body (quotes already stripped) with the
 * full TOML escape set including \uXXXX and \UXXXXXXXX. Returns
 * NULL on a malformed escape. */
static inline const char* tom_decode_basic(bbq_arena* a, peg_span s) {
    char* d = (char*)bbq_arena_alloc(a, (size_t)(s.len + 1));
    int j = 0;
    for (int i = 0; i < s.len; ) {
        char c = s.ptr[i];
        if (c != '\\' || i + 1 >= s.len) {
            d[j++] = c; i++; continue;
        }
        char n = s.ptr[i + 1];
        switch (n) {
            case '"':  d[j++] = '"';  i += 2; break;
            case '\\': d[j++] = '\\'; i += 2; break;
            case 'b':  d[j++] = '\b'; i += 2; break;
            case 'f':  d[j++] = '\f'; i += 2; break;
            case 'n':  d[j++] = '\n'; i += 2; break;
            case 'r':  d[j++] = '\r'; i += 2; break;
            case 't':  d[j++] = '\t'; i += 2; break;
            case 'u': {
                if (i + 6 > s.len) return NULL;
                uint32_t cp = 0;
                for (int k = 0; k < 4; k++) {
                    char h = s.ptr[i + 2 + k];
                    int dv;
                    if      (h >= '0' && h <= '9') dv = h - '0';
                    else if (h >= 'a' && h <= 'f') dv = 10 + (h - 'a');
                    else if (h >= 'A' && h <= 'F') dv = 10 + (h - 'A');
                    else return NULL;
                    cp = (cp << 4) | (uint32_t)dv;
                }
                if (cp >= 0xD800 && cp <= 0xDFFF) return NULL;
                j += tom_utf8_encode(cp, d + j);
                i += 6;
                break;
            }
            case 'U': {
                if (i + 10 > s.len) return NULL;
                uint32_t cp = 0;
                for (int k = 0; k < 8; k++) {
                    char h = s.ptr[i + 2 + k];
                    int dv;
                    if      (h >= '0' && h <= '9') dv = h - '0';
                    else if (h >= 'a' && h <= 'f') dv = 10 + (h - 'a');
                    else if (h >= 'A' && h <= 'F') dv = 10 + (h - 'A');
                    else return NULL;
                    cp = (cp << 4) | (uint32_t)dv;
                }
                if (cp >= 0x110000) return NULL;
                if (cp >= 0xD800 && cp <= 0xDFFF) return NULL;
                j += tom_utf8_encode(cp, d + j);
                i += 10;
                break;
            }
            default:
                /* Unknown escape — pass through (lenient). */
                d[j++] = n; i += 2; break;
        }
    }
    d[j] = '\0';
    return d;
}

