/* ── String span helpers (operate on full token span incl. delims) ── */

/* Decode a captured `basic_string` span (with surrounding "). */
static inline const char* tom_decode_basic_span(bbq_arena* a, peg_span full) {
    peg_span body = { full.ptr + 1, full.len - 2 };
    return tom_decode_basic(a, body);
}

/* Decode a captured `ml_basic_string` span (with surrounding """).
 * Strips optional leading newline immediately after opening. */
static inline const char* tom_decode_ml_basic_span(bbq_arena* a, peg_span full) {
    peg_span body = { full.ptr + 3, full.len - 6 };
    if (body.len > 0 && body.ptr[0] == '\n') {
        body.ptr++; body.len--;
    } else if (body.len > 1 && body.ptr[0] == '\r' && body.ptr[1] == '\n') {
        body.ptr += 2; body.len -= 2;
    }
    return tom_decode_ml_basic(a, body);
}

/* Strip exactly `q` quote chars from each end of a literal span
 * (single-line: q=1, multiline: q=3). Multiline also strips one
 * leading newline immediately after opening per spec. */
static inline const char* tom_literal_span(bbq_arena* a, peg_span full, int q) {
    peg_span body = { full.ptr + q, full.len - 2 * q };
    if (q == 3) {
        if (body.len > 0 && body.ptr[0] == '\n') {
            body.ptr++; body.len--;
        } else if (body.len > 1 && body.ptr[0] == '\r' && body.ptr[1] == '\n') {
            body.ptr += 2; body.len -= 2;
        }
    }
    return tstr_ndup(a, body.ptr, body.len);
}

